package com.example.routing;
import java.net.URI;import java.net.http.*;import java.time.Duration;
public final class RoutingClient{private final String base;private final HttpClient h=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).build();public RoutingClient(String b){base=b.replaceAll("/$","");}public String route(String id,String summary)throws Exception{var q=HttpRequest.newBuilder(URI.create(base+"/v1/route")).timeout(Duration.ofSeconds(10)).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString("{\"ticket_id\":\""+id+"\",\"summary\":\""+summary.replace("\"","\\\"")+"\"}")).build();var r=h.send(q,HttpResponse.BodyHandlers.ofString());if(r.statusCode()/100!=2)throw new IllegalStateException(r.body());return r.body();}public static void main(String[]a)throws Exception{System.out.println(new RoutingClient(a.length>0?a[0]:"http://127.0.0.1:8000").route("T-DEMO","Cannot connect to corporate VPN"));}}
